// The third argument is a source variant: variant('value', v) inline,
// or variant('file', path) for a beast2 file adopted at deploy.
const name = e3.input('name', StringType, variant('value', 'default'));
// Omitted: unassigned until something sets it.
const count = e3.input('count', IntegerType);

// A large table delivered as a beast2 file. Only the path travels in the
// package; deploy checks the file against the declared type and takes it in
// as the value — a collection a segment at a time, as the store's own
// segments, never read whole and never modified — so a new delivery stores
// only the segments that changed, and only its consumers re-run.
const RowType = StructType({ id: IntegerType, site: StringType });
const table = e3.input('table', ArrayType(RowType), variant('file', './deliveries/TABLE.beast2'));

// Point it at a new delivery without a redeploy:
//   e3 dataset set . dev.table --from-file ./deliveries/TABLE-v2.beast2

// Define a task that runs an East function
const name = e3.input('name', StringType, variant('value', 'World'));

const greet = e3.task(
  'greet',
  [name],
  East.function([StringType], StringType, ($, n) =>
    East.str`Hello, ${n}!`
  )
);

// Chain tasks via .output
const name = e3.input('name', StringType, variant('value', 'World'));

const greet = e3.task(
  'greet',
  [name],
  East.function([StringType], StringType, ($, n) =>
    East.str`Hello, ${n}!`
  )
);

const shout = e3.task(
  'shout',
  [greet.output],
  East.function([StringType], StringType, ($, s) => s.upperCase())
);

const input = e3.input('input', IntegerType, variant('value', 21n));

// A stock runtime and the platforms it loads: a typo, or another runtime's
// platform, is a compile error.
const pyTask = e3.task(
  'py_task',
  [input],
  East.function([IntegerType], IntegerType, ($, x) => x.multiply(2n)),
  { runner: { runtime: 'east-py', platforms: ['east-py-std'] } }
);

// Any other command is the custom runtime: e3 runs it with `run`'s arguments
// appended — -i <input> for each input, -o <output>, then the program's file.
const wrapped = e3.task(
  'wrapped',
  [input],
  East.function([IntegerType], IntegerType, ($, x) => x.multiply(2n)),
  { runner: { runtime: 'custom', command: ['uv', 'run', 'east-py', 'run', '-p', 'east-py-std'] } }
);

// Define a task that runs a shell command: it builds a bash script from the
// staged input files' paths and the path it writes the output to.
const rawData = e3.input('raw_data', StringType, variant('value', 'hello'));
const process = e3.customTask(
  'process',
  [rawData],
  StringType,
  ($, input_paths, output_path) =>
    East.str`python script.py -i ${input_paths.get(0n)} -o ${output_path}`
);

// Bundle into a package — pass the last tasks: what they depend on is collected —
// and export it to a zip.
const input = e3.input('input', IntegerType, variant('value', 21n));
const finalTask = e3.task('final_task', [input], East.function([IntegerType], IntegerType, ($, x) => x.multiply(2n)));

const pkg = e3.package('myapp', '1.0.0', finalTask);
await e3.export(pkg, '/tmp/myapp.zip');
export default pkg;

// Complete e3 package with input, task, package, and export
const name = e3.input('name', StringType, variant('value', 'World'));

const greet = e3.task(
  'greet',
  [name],
  East.function([StringType], StringType, ($, n) =>
    East.str`Hello, ${n}!`
  )
);

const pkg = e3.package('hello', '1.0.0', greet);
await e3.export(pkg, '/tmp/hello.zip');
export default pkg;

const url = 'http://localhost:3000';            // e3-api-server --repos ./repos
const opts = { token: null };                   // a server with auth: the token `e3 auth token <server>` prints

await repoCreate(url, 'demo', opts);
const pkg = await packageImport(url, 'demo', readFileSync('hello.zip'), opts);
await workspaceCreate(url, 'demo', 'dev', opts);
await workspaceDeploy(url, 'demo', 'dev', `${pkg.name}@${pkg.version}`, opts);   // a job, polled to its end

const run = await dataflowExecute(url, 'demo', 'dev', {}, opts);                  // starts the run and polls it
// A dataset's path is a TreePath — a definition's `.path`, or built from its fields:
const greeting = [variant('field', 'tasks'), variant('field', 'greet'), variant('field', 'output')];
const { data } = await datasetGet(url, 'demo', 'dev', greeting, opts);
console.log(run.success, decodeBeast2For(StringType)(data));                     // true 'Hello, World!'

// Source/IR input -> PNG (and optional standalone HTML):
await renderToPng({
  input: { path: './dashboard.tsx' },
  output: 'dashboard.png',
  html: 'dashboard.html',
});

// A deployed e3 task's computed output:
await renderTaskToPng({ repo: './.repos', workspace: 'main', task: 'dashboard', output: 'dashboard.png' });

const SaleKeyType = StructType({ sku: StringType, id: IntegerType });
const SaleType = StructType({ amount: FloatType, currency: StringType });
const sales = e3.input('sales', DictType(SaleKeyType, SaleType));
const rates = e3.input('rates', DictType(StringType, FloatType));

// e3.partition splits the work over `sales`: the body runs once per piece — a
// key range, cut by content — each piece a cached unit, run in parallel. `rates`
// reaches every piece whole, opened lazily when large. A key emitted more than
// once, in one piece or across pieces, folds with `merge`.
const bySku = e3.streamTask('by_sku', {
  inputs: [e3.partition(sales), rates],
  output: e3.output.dict(StringType, FloatType, { merge: ($, _sku, a, b) => a.add(b) }),
}, ($, sales, rates, emit) => {
  $.for(sales, ($, sale, key) => {
    $(emit(key.sku, sale.amount.multiply(rates.get(sale.currency))));
  });
});

// `by` names leading key fields: rows whose `by` fields are equal are never
// split across pieces, so each piece holds whole SKUs, in key order.
const perSku = e3.streamTask('per_sku', {
  inputs: [e3.partition(sales, { by: ['sku'] })],
  output: e3.output.array(FloatType),
}, ($, sales, emit) => {
  const sku = $.let('');
  const total = $.let(0.0);
  $.for(sales, ($, sale, key) => {
    $.if(East.notEqual(key.sku, sku), ($) => {   // the next SKU starts from zero
      $.assign(sku, key.sku);
      $.assign(total, 0.0);
    });
    $.assign(total, total.add(sale.amount));
    $(emit(total));
  });
});

const EventType = StructType({ account: StringType, amount: FloatType });
const events = e3.input('events', ArrayType(EventType));

// A stream task emits its output into an output kind, which fixes emit's
// signature and how the parts of the output combine. Emission order is free.
// With no partitioned input the task is one unit, exact left to right.
const balances = e3.streamTask('balances', {
  inputs: [events],
  output: e3.output.array(FloatType),
}, ($, events, emit) => {
  const balance = $.let(0.0);
  $.for(events, ($, event) => {
    $.assign(balance, balance.add(event.amount));
    $(emit(balance));
  });
});

// A Set holds an element emitted twice once.
const accounts = e3.streamTask('accounts', {
  inputs: [e3.partition(events)],
  output: e3.output.set(StringType),
}, ($, events, emit) => {
  $.for(events, ($, event) => { $(emit(event.account)); });
});

// A fold folds every emitted value with `combine`, from `zero`.
const total = e3.streamTask('total', {
  inputs: [e3.partition(events)],
  output: e3.output.fold(FloatType, { zero: 0.0, combine: ($, a, b) => a.add(b) }),
}, ($, events, emit) => {
  $.for(events, ($, event) => { $(emit(event.amount)); });
});

const RowType = StructType({ id: StringType, at: IntegerType });

// A producer has no inputs: it reads platform sources (paged APIs, database
// cursors) and emits. Emission order is free — the runner sorts a Dict output
// in runs of bounded size — and a key emitted twice folds with `merge`: here
// the latest row wins.
const rows = e3.streamTask('ingest', {
  inputs: [],
  output: e3.output.dict(StringType, RowType, {
    merge: ($, _id, a, b) => East.greater(a.at, b.at).ifElse(($) => a, ($) => b),
  }),
}, ($, emit) => { /* fetch pages, $(emit(row.id, row)) each */ });

const PlanType = StructType({ title: StringType, owner: StringType });
const plans = e3.record('plans', DictType(StringType, PlanType), new Map());

// reduce: the reducer returns the whole new state — any record.
const addPlan = e3.mutation.reduce('add_plan', plans,
  East.function([plans.type, StringType, PlanType], plans.type, ($, state, id, plan) => {
    const next = $.let(state.copy());   // the state is a frozen input
    $(next.insert(id, plan));
    return next;
  }));

// edit: reads the state lazily and writes through `edit`, so a write costs the
// segments it touches — a Dict or Set record.
const reassign = e3.mutation.edit('reassign', plans,
  East.function([plans.type, StringType, StringType, e3.mutation.editType(plans.type)], NullType,
    ($, state, id, owner, edit) => { $(edit.set(id, { title: state.get(id).title, owner })); }));

// An index: a second collection in another order, maintained in the same commit.
const byOwner = e3.recordIndex('by_owner', plans, {
  key: East.function([StringType, PlanType], StringType, ($, _id, plan) => plan.owner),
});

// patch: no body — the argument is the change, a PatchType of the state.
const pkg = e3.package('planning', '1.0.0', plans, addPlan, reassign, e3.mutation.patch(plans), byOwner);

const RowV1Type = StructType({ title: StringType });
const RowV2Type = StructType({ title: StringType, owner: StringType });
const plans = e3.record('plans', DictType(StringType, RowV2Type), new Map());

// A deploy runs the steps a workspace has not applied, in order, a
// `$migrate:<name>` commit each; once applied, a step is known by its name.
// rows: a Dict's rows, one at a time and a piece at a time; rekey changes the
// keys too, and value takes the whole state.
const addOwner = e3.migration.rows('add_owner', plans,
  East.function([StringType, RowV1Type], RowV2Type,
    ($, _id, row) => ({ title: row.title, owner: 'unassigned' })));

// The next version's step names this one: { after: addOwner }.
const pkg = e3.package('planning', '2.0.0', plans, addOwner);
// e3 workspace deploy <repo> <ws> --from-zip planning.zip --plan   → what it would do; writes nothing
